let data = items[0].json.output || items[0].json;

if (typeof data === "string") {
  data = JSON.parse(data);
}

return [{ json: data }];

// Raw AI output
let raw = $('AI Agent1').first().json.output;

if (!raw || typeof raw !== "string") {
  return {
    valid: false,
    type: "invalid",
    cleanInput: "",
    brandColor: "",
    insight: "",
  };
}

// Remove markdown wrappers
raw = raw.replace(/```json/gi, "")
         .replace(/```/g, "")
         .trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return {
    valid: false,
    type: "invalid",
    cleanInput: "",
    brandColor: "",
    insight: "",
  };
}

// 🔥 Auto-assign type if missing
let type = parsed.inputType || "";

// If no type but valid + cleanInput exists → assume TOPIC
if (!type && parsed.valid === true && parsed.cleanInput) {
  type = "topic";
}

// If no type but image metadata exists → assume IMAGE
if (!type && parsed.valid === true && parsed.isImage === true) {
  type = "image";
}

// Safety fallback
if (!type) type = "invalid";

// Final output
return {
  valid: parsed.valid === true,
  type,
  cleanInput: parsed.cleanInput || "",
  brandColor: parsed.brandColor || "",
  insight: parsed.insight || "",
  messageToUser: parsed.messageToUser || ""
};

